/**
 * @module O 内容工具箱
 *
 * recipe.template 投影器——把 Resource Graph 中的 recipe.template 节点投影回
 * oblivions/gamedata/recipe_table.php 的 PHP 数组形态。
 *
 * 设计意图（执行案 06-P5 §4.3.2）：
 * - P5-2 改用 generatePhpFile API：文件头注入 `// AUTO-GENERATED FROM ...` 注释、
 *   模块标签与 sectionTitle 由 schema.projectionTargets 派生，不再使用硬编码文件头。
 * - recipe_table.php 无 name 字段——后端 item_get_visible_recipes() 通过首产物 itm
 *   投影 name 作为 fallback（item.craft.func.php:544-552），故投影器不输出 name 字段。
 * - 字段顺序按节点 data 的 key 插入顺序保留（TS 对象保留 string key 顺序），
 *   节点数组顺序保留为顶层 recipe_id 顺序。
 * - 三层嵌套（materials[] / results[]）由 renderPhpValue 递归输出，无需特殊处理。
 *
 * 字段映射：
 *   - 节点 id              → 顶层 key（recipe ID，如 'craft_bandage'）
 *   - node.data.{field}    → entry 字段（category / materials / results）
 *
 * 边界：
 * - 节点 data 为 null/非对象时跳过该节点
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 * - materials/results 空数组输出为 `[]`
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='recipe.template' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const RECIPE_TABLE_FILE_PATH = 'oblivions/gamedata/recipe_table.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const RECIPE_TABLE_AUTHOR_SOURCE = 'oblivions/content/recipes/recipes.yaml';

/**
 * 把 recipe.template 节点投影回 recipe_table.php 形态。
 *
 * @param nodes recipe.template 节点数组（顺序保留为顶层 recipe_id 顺序）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/recipe_table.php）
 */
export function projectRecipeTable(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildRecipeTableDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'F 物品系统',
    sectionTitle: 'Oblivions 合成配方表',
    autoGeneratedFrom: RECIPE_TABLE_AUTHOR_SOURCE,
  });
  return [{ filePath: RECIPE_TABLE_FILE_PATH, content }];
}

/**
 * 把 ResourceNode[] 重建为 map-keyed PHP 字典形态。
 *
 * 节点 id 作为顶层 key（recipe ID），node.data 作为 value（含 category / materials / results）。
 * stripUndefinedFields 递归移除 undefined 字段。
 *
 * 三层嵌套（materials → entries）由 renderPhpValue 递归处理，无需特殊代码。
 */
function buildRecipeTableDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const cleaned = stripUndefinedFields(node.data);
    dict[node.id] = cleaned as PhpValue;
  }
  return dict;
}

/**
 * 递归移除 undefined 字段——与 php-adapter.stripUndefinedFields 行为一致。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
